import{_ as n,C as t,o as i,c as s,E as o,a2 as r}from"./chunks/framework.Cm6XCzck.js";const k=JSON.parse('{"title":"开源工程每日观察 003 — Manager 编排与 Handoff 表达不同的工作所有权模型","description":"","frontmatter":{"title":"开源工程每日观察 003 — Manager 编排与 Handoff 表达不同的工作所有权模型","date":"2026-08-02","column":"open-source-engineering","category":"daily","summary":"OpenAI Agents SDK 把 Manager 调用 Specialist 与转移 Active Control 的 Handoff 分开，说明多 Agent 设计必须显式建模 Ownership 与 Authority，不能把所有 Delegation 都当成同一种 Tool Call。","sources":["OpenAI Agents SDK agent orchestration documentation","OpenAI Agents SDK handoffs, guardrails, and tracing documentation"],"outline":"deep","cover":"/assets/covers/manager-handoff-ownership-models-cover-v2.jpg"},"headers":[],"relativePath":"zh/engineering/2026-08-02-manager-handoff-ownership-models.md","filePath":"zh/engineering/2026-08-02-manager-handoff-ownership-models.md","lastUpdated":1787407830000}'),l={name:"zh/engineering/2026-08-02-manager-handoff-ownership-models.md"};function p(d,a,h,c,g,u){const e=t("ArticleCover");return i(),s("div",null,[o(e,{image:"/assets/covers/manager-handoff-ownership-models-cover-v2.jpg",kicker:"开源工程 · 每日观察 003",title:"Manager 编排与 Handoff 表达不同的工作所有权模型",summary:"保留控制权调用 Specialist，与把活动会话和责任转交出去，不是同一种操作。",version:"ED003",status:"Production Test V1 · 2026-08-02",languageHref:"/en/engineering/2026-08-02-manager-handoff-ownership-models",languageLabel:"English"}),a[0]||(a[0]=r(`<h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>OpenAI Agents SDK 提供两种常见的 Multi-agent Composition Pattern。</p><p>在 <strong>Manager Pattern</strong> 中，一个 Agent 保留面向用户的 Conversation，并把 Specialist Agent 当成 Tool 调用。Manager 组合这些输出，并继续对最终答案负责。</p><p>在 <strong>Handoff Pattern</strong> 中，Triage Agent 或当前 Agent 把控制权转交给 Specialist。Specialist 成为 Active Agent；除非 Context 被过滤，否则它会接收此前 Conversation History，并负责后续响应。</p><p>Research Center 的判断是：</p><blockquote><p>Manager Call 与 Handoff 不是风格上的替代方案，而是不同的 Ownership、Authority、Context、Guardrail 与 Completion Model。可靠的 Multi-agent Runtime 必须记录实际发生了哪一种操作。</p></blockquote><p>如果把两者都称为泛化的“Delegation”，就会隐藏最关键的运营事实：跨越边界以后，工作由谁拥有。</p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><h3 id="入选的一手资料" tabindex="-1">入选的一手资料 <a class="header-anchor" href="#入选的一手资料" aria-label="Permalink to &quot;入选的一手资料&quot;">​</a></h3><ol><li><strong>OpenAI Agents SDK Agent orchestration 与 Agents 文档</strong>：入选原因是它显式比较 Agents-as-tools 与 Handoff，并解释 Central Manager 应在什么情况下保留控制权。</li><li><strong>Handoffs 文档</strong>：入选原因是它定义 Transfer Behavior、History Forwarding、Input Filter、Handoff Metadata，以及 Handoff 仍位于同一次 Run 内。</li><li><strong>Guardrails 文档</strong>：入选原因是它暴露 Initial Input、Final Output、Function Tool、Hosted Tool 与 Handoff 的不同 Validation Boundary。</li><li><strong>Tracing 文档</strong>：入选原因是它把 Agent Span、Generation、Function Call、Guardrail 与 Handoff 记录成不同 Runtime Event。</li></ol><p>这些资料定义 SDK 行为。以下架构判断是对已记录机制的综合，并不意味着某一种 SDK Pattern 在所有场景都更好。</p><h2 id="observation" tabindex="-1">Observation <a class="header-anchor" href="#observation" aria-label="Permalink to &quot;Observation&quot;">​</a></h2><h3 id="_1-manager-保留会话和完成所有权" tabindex="-1">1. Manager 保留会话和完成所有权 <a class="header-anchor" href="#_1-manager-保留会话和完成所有权" aria-label="Permalink to &quot;1. Manager 保留会话和完成所有权&quot;">​</a></h3><p>当 Specialist 通过 <code>Agent.as_tool()</code> 暴露时，Manager 为一个有边界的 Subtask 调用它。Specialist 把结果返回 Manager；Manager 仍然是 Active Agent，决定是否还需要更多工作，组合响应，并拥有最终 User-facing Output。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Manager Agent</span></span>
<span class="line"><span>  ├── Call Specialist A as Tool</span></span>
<span class="line"><span>  ├── Call Specialist B as Tool</span></span>
<span class="line"><span>  └── Integrate and Answer</span></span></code></pre></div><p>当一个组件必须执行统一政策、组合多个发现、保持单一表达，或者继续对完成负责时，这种 Pattern 更合适。</p><h3 id="_2-handoff-转移活动角色" tabindex="-1">2. Handoff 转移活动角色 <a class="header-anchor" href="#_2-handoff-转移活动角色" aria-label="Permalink to &quot;2. Handoff 转移活动角色&quot;">​</a></h3><p>Handoff 以 <code>transfer_to_refund_agent</code> 等 Transfer Operation 形式暴露给模型。调用以后，Receiving Agent 接管 Conversation。它通常会接收此前 Conversation History，但 Input Filter 或 Nested-history Setting 可以改变转交内容。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Triage Agent</span></span>
<span class="line"><span>  ↓ Handoff Event</span></span>
<span class="line"><span>Specialist Agent becomes Active</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Specialist responds and owns the next turn</span></span></code></pre></div><p>因此，Handoff 会改变 Active Instruction Set、Available Tool、Contextual View，以及对 Final Output 的责任。</p><h3 id="_3-validation-boundary-不相同" tabindex="-1">3. Validation Boundary 不相同 <a class="header-anchor" href="#_3-validation-boundary-不相同" aria-label="Permalink to &quot;3. Validation Boundary 不相同&quot;">​</a></h3><p>SDK 文档暴露了多个重要边界：</p><ul><li>Input Guardrail 只应用于 Chain 中第一个 Agent；</li><li>Output Guardrail 只应用于产生最终输出的 Agent；</li><li>Function-tool Guardrail 可以包围每次 Function Tool Invocation；</li><li>Handoff 使用独立的 Handoff Pipeline，而不是普通 Function-tool Guardrail Pipeline；</li><li>Hosted Tool 与 Built-in Execution Tool 具有自己的 Safety 与 Control Boundary。</li></ul><p>如果系统假设“所有 Delegation 都被同一套 Guardrail 覆盖”，就可能产生未受保护的 Transition。</p><h3 id="_4-tracing-把两种操作记录成不同-event" tabindex="-1">4. Tracing 把两种操作记录成不同 Event <a class="header-anchor" href="#_4-tracing-把两种操作记录成不同-event" aria-label="Permalink to &quot;4. Tracing 把两种操作记录成不同 Event&quot;">​</a></h3><p>Agents SDK 在 Trace 中分别记录 Function Call 与 Handoff Span。这不只是可观测性便利，而是对应不同 Runtime Semantics：Function Result 返回 Caller；Handoff 则改变 Active Agent Path。</p><h2 id="discussion" tabindex="-1">Discussion <a class="header-anchor" href="#discussion" aria-label="Permalink to &quot;Discussion&quot;">​</a></h2><h3 id="ownership-比较" tabindex="-1">Ownership 比较 <a class="header-anchor" href="#ownership-比较" aria-label="Permalink to &quot;Ownership 比较&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>Manager / Agent as Tool</th><th>Handoff</th></tr></thead><tbody><tr><td>Active Conversation Owner</td><td>Manager 保持 Active</td><td>Specialist 成为 Active</td></tr><tr><td>Specialist Scope</td><td>有边界的 Subtask</td><td>后续 Turn 或 Workflow Responsibility</td></tr><tr><td>Final Response Owner</td><td>Manager</td><td>Receiving Specialist</td></tr><tr><td>Context Flow</td><td>Manager 选择的 Structured Call Input 与 Local Context</td><td>默认转交 Conversation History，可通过 Filter 调整</td></tr><tr><td>Shared Policy Point</td><td>Central Manager 可一致执行政策</td><td>Policy 必须跨 Receiving Agent 与 Transition 保持有效</td></tr><tr><td>适用场景</td><td>Research、Calculation、Review、Bounded Expertise、Aggregation</td><td>Triage、Domain Transfer、Direct Specialist Interaction</td></tr><tr><td>主要风险</td><td>Manager 成为 Bottleneck 或扭曲 Specialist Output</td><td>Ownership Transfer 隐式发生或丢失必要 Context</td></tr></tbody></table><p><em>表：joinwell52 Research Center 根据 OpenAI Agents SDK 文档综合。</em></p><h3 id="delegation-需要明确-operation-type" tabindex="-1">Delegation 需要明确 Operation Type <a class="header-anchor" href="#delegation-需要明确-operation-type" aria-label="Permalink to &quot;Delegation 需要明确 Operation Type&quot;">​</a></h3><p>Multi-agent Task Record 不应只有 <code>from</code> 和 <code>to</code>，还必须说明为什么需要另一 Agent，以及责任是否改变。</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">delegation_event</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">consult | assign_subtask | handoff | escalate | return</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  from_actor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  to_actor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  work_scope</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  authority_snapshot_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  context_package_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  expected_output_contract</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  completion_owner_before</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  completion_owner_after</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  guardrail_profile_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  evidence_refs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span></code></pre></div><p>这个结构可以防止一次“Specialist Call”悄悄变成 Authority Transfer。</p><h3 id="handoff-不等于创建-child-task" tabindex="-1">Handoff 不等于创建 Child Task <a class="header-anchor" href="#handoff-不等于创建-child-task" aria-label="Permalink to &quot;Handoff 不等于创建 Child Task&quot;">​</a></h3><p>Child Task 可以异步执行，同时 Parent Owner 继续负责 Integration 与 Closure。Handoff 通常转移活动会话角色。二者可以组合，但不应混同。</p><p>例如：</p><ul><li>PM 请求 QA 提供有边界的 Verification Report：属于 <strong>Subtask/Consult</strong>，PM 保留最终 Ownership。</li><li>ADMIN 把 Operational Incident 转给 OPS，并授予 Recovery Management 权限：属于 <strong>Handoff 或 Assignment</strong>，Ownership 可能改变。</li><li>QA 发现 Policy Exception 并返回 ADMIN：属于 <strong>Escalation</strong>，Decision Authority 改变，但 Execution Ownership 不一定改变。</li></ul><p>Runtime 必须表示这些区别，而不能从自然语言 Message 中猜测。</p><h3 id="context-transfer-应是受治理-package" tabindex="-1">Context Transfer 应是受治理 Package <a class="header-anchor" href="#context-transfer-应是受治理-package" aria-label="Permalink to &quot;Context Transfer 应是受治理 Package&quot;">​</a></h3><p>转交完整 Conversation 很方便，但可能暴露不必要数据、过期 Instruction 或不可信 Tool Output。Production Handoff 应建立 Context Package，至少包含：</p><ul><li>Task Identity 与 Objective；</li><li>已接受 Fact 与 Evidence Reference；</li><li>未解决问题；</li><li>Authority 与 Policy Snapshot；</li><li>Allowed Tool 与 Data Scope；</li><li>Expected Output Contract；</li><li>Explicit Exclusion；</li><li>Return 或 Escalation Condition。</li></ul><p>Receiving Agent 不应从长 Transcript 中自行重建 Authority。</p><h3 id="completion-必须跟随-ownership" tabindex="-1">Completion 必须跟随 Ownership <a class="header-anchor" href="#completion-必须跟随-ownership" aria-label="Permalink to &quot;Completion 必须跟随 Ownership&quot;">​</a></h3><p>Manager 保留 Ownership 时，Specialist Success 只代表“Subtask Result 已返回”，不代表 Parent Work 完成。Handoff 转移 Ownership 时，Completion Gate、Output Validation 与 Release Authority 必须明确移动或重新绑定。</p><p>这就是只会路由 Text 的 Orchestration Graph，与真正治理工作运行的系统之间的区别。</p><h2 id="engineering-impact" tabindex="-1">Engineering Impact <a class="header-anchor" href="#engineering-impact" aria-label="Permalink to &quot;Engineering Impact&quot;">​</a></h2><h3 id="tmpa" tabindex="-1">TMPA <a class="header-anchor" href="#tmpa" aria-label="Permalink to &quot;TMPA&quot;">​</a></h3><p>本笔记不直接修改 TMPA 正式出版物。它为 Message Transfer、Work Assignment、Authority Transfer、Custody 与 Completion Ownership 的分离提供研究输入。确定性重建不仅要显示谁执行了动作，还要显示这次 Interaction 属于 Consultation、Subtask、Handoff、Escalation 还是 Return。</p><h3 id="digital-employee" tabindex="-1">Digital Employee <a class="header-anchor" href="#digital-employee" aria-label="Permalink to &quot;Digital Employee&quot;">​</a></h3><p>数字员工 Position Definition 应明确：</p><ul><li>哪些工作可以直接接受；</li><li>可以咨询哪些 Specialist；</li><li>哪些工作可以 Handoff；</li><li>哪些 Authority 可以转移；</li><li>谁继续对最终完成负责；</li><li>Transfer 必须携带哪些 Context 与 Evidence。</li></ul><p>数字员工平台应把 Current Work Owner 与 Contributor 分开显示。</p><h3 id="codeflowmu" tabindex="-1">CodeFlowMu <a class="header-anchor" href="#codeflowmu" aria-label="Permalink to &quot;CodeFlowMu&quot;">​</a></h3><p>CodeFlowMu 的 PM Pattern 天然接近 Manager Orchestration：PM 拆分工作，调用 DEV/QA/OPS，整合 Evidence，再向 ADMIN 报告。对于有边界的 Specialist Work，这应继续作为默认方式。</p><p>Handoff 应只用于显式责任转移。Runtime 应新增 Typed Delegation Event，并显示：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Current Owner</span></span>
<span class="line"><span>Contributors</span></span>
<span class="line"><span>Pending Subtask Owners</span></span>
<span class="line"><span>Decision Authority</span></span>
<span class="line"><span>Release Authority</span></span>
<span class="line"><span>Last Handoff or Return Event</span></span></code></pre></div><p>FCoP Lifecycle Transition 可以保留 Custody，但产品不应只从 File Movement 推断 Orchestration Semantics。Task Metadata 与 Runtime Event 应明确写出 Operation Type。</p><h2 id="future-work" tabindex="-1">Future Work <a class="header-anchor" href="#future-work" aria-label="Permalink to &quot;Future Work&quot;">​</a></h2><ol><li>为 Research OS 与 CodeFlowMu Runtime 增加 Typed Delegation Semantics。</li><li>定义 Handoff 与 Escalation 的最小 Context Package。</li><li>在同一开发任务上测试 Manager、Parallel Subtask、Sequential Handoff 与 Return-to-manager Pattern。</li><li>验证每个边界上的 Guardrail Coverage，包括 Hosted Tool 与 Handoff。</li><li>比较 Trace Evidence、FCoP Lifecycle Event 与 Report。</li><li>定义 Handoff Chain 之后由哪个 Agent 有权声明 Parent Completion。</li></ol><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ol><li>OpenAI Agents SDK，<strong>Agent orchestration</strong>：<a href="https://openai.github.io/openai-agents-python/multi_agent/" target="_blank" rel="noreferrer">https://openai.github.io/openai-agents-python/multi_agent/</a></li><li>OpenAI Agents SDK，<strong>Agents</strong>：<a href="https://openai.github.io/openai-agents-python/agents/" target="_blank" rel="noreferrer">https://openai.github.io/openai-agents-python/agents/</a></li><li>OpenAI Agents SDK，<strong>Handoffs</strong>：<a href="https://openai.github.io/openai-agents-python/handoffs/" target="_blank" rel="noreferrer">https://openai.github.io/openai-agents-python/handoffs/</a></li><li>OpenAI Agents SDK，<strong>Guardrails</strong>：<a href="https://openai.github.io/openai-agents-python/guardrails/" target="_blank" rel="noreferrer">https://openai.github.io/openai-agents-python/guardrails/</a></li><li>OpenAI Agents SDK，<strong>Tracing</strong>：<a href="https://openai.github.io/openai-agents-python/tracing/" target="_blank" rel="noreferrer">https://openai.github.io/openai-agents-python/tracing/</a></li></ol>`,62))])}const m=n(l,[["render",p]]);export{k as __pageData,m as default};
